// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class LmdbFusedRuntimeTelemetryTest {

	@Test
	void mergesRuntimeSipFactorizationAndFilterTelemetryAcrossWorkers() throws Exception {
		LmdbFusedSipFactorizedRuntime.Session root = LmdbFusedSipFactorizedRuntime.create(17L, 1 << 20, true);
		try {
			try (LmdbFusedSipFactorizedRuntime.Scope ignored = LmdbFusedSipFactorizedRuntime.attach(root)) {
				long[] domain = { 2L, 4L, 7L, 11L };
				LmdbFusedKernelRuntime.installExactDomain(0, "?enc", "hasEncounter.object", domain, 0,
						domain.length);
				LmdbFusedKernelRuntime.registerDomainConsumer(0, "recordedOn.subject");
				assertTrue(LmdbFusedKernelRuntime.sipMayContain(0, 2L));
				assertFalse(LmdbFusedKernelRuntime.sipMayContain(0, 3L));
				LmdbFusedKernelRuntime.markNestedKernelFactorization();
				LmdbFusedKernelRuntime.recordFactorizedLevel(3, 3, 24, 6, 18, 1, 24, 2);
				LmdbFusedKernelRuntime.materializationBoundary(3);
				LmdbFusedKernelRuntime.recordGeneratedFilterPlacement(7, "?date >= cutoff", 3, 1);
				LmdbFusedKernelRuntime.observeGeneratedFilter(7, "?date >= cutoff", 3, 1, 10, 2, 100,
						40);
			}

			Thread worker = new Thread(() -> {
				try (LmdbFusedSipFactorizedRuntime.Scope ignored = LmdbFusedSipFactorizedRuntime.inherit(root)) {
					assertTrue(LmdbFusedKernelRuntime.sipMayContain(0, 7L));
					assertFalse(LmdbFusedKernelRuntime.sipMayContain(0, 8L));
					// A worker ordinal window must not replace the root domain or reset its counters.
					LmdbFusedKernelRuntime.installExactDomain(0, "worker-window", "worker", new long[] { 7L },
							0, 1);
				}
			});
			worker.start();
			worker.join();

			LmdbFusedSipFactorizedRuntime.Telemetry telemetry = root.telemetry();
			assertTrue(telemetry.runtimeSipUsed());
			assertEquals(4, telemetry.sipTests());
			assertEquals(2, telemetry.sipRejects());
			assertEquals(1, telemetry.domains().size());
			LmdbFusedSipFactorizedRuntime.DomainTelemetry domain = telemetry.domains().get(0);
			assertEquals("?enc", domain.label());
			assertEquals("hasEncounter.object", domain.producer());
			assertEquals("EXACT_SORTED", domain.representation());
			assertEquals(4, domain.tests());
			assertEquals(2, domain.rejects());
			assertTrue(domain.consumers().contains("recordedOn.subject"));

			LmdbFusedSipFactorizedRuntime.FactorizationTelemetry factorization = telemetry.factorization();
			assertTrue(factorization.used());
			assertTrue(factorization.modes().contains("NESTED_KERNEL"));
			assertEquals(24, factorization.candidateRows());
			assertEquals(6, factorization.storedLanes());
			assertEquals(18, factorization.rejectedBeforeMaterialization());
			assertEquals(1, factorization.materializationBoundaries());
			assertEquals(3, factorization.flattenedRows());

			assertEquals(1, telemetry.filters().size());
			LmdbFusedSipFactorizedRuntime.FilterTelemetry filter = telemetry.filters().get(0);
			assertEquals(3, filter.originalStage());
			assertEquals(1, filter.selectedStage());
			assertEquals(10, filter.tested());
			assertEquals(2, filter.accepted());
			assertEquals(40, filter.downstreamRowsAvoided());
			assertEquals(1, telemetry.filtersRelocated());
		} finally {
			root.close();
		}
	}

	/**
	 * The executed telemetry must name which kernel implementation served each bind (the generated class or the
	 * interpreter) and through which route, aggregated across parallel workers — a hosted/island invocation otherwise
	 * shows only the outer decline and never the kernel that actually ran.
	 */
	@Test
	void recordsKernelIdentityPerBindAcrossWorkers() throws Exception {
		LmdbFusedSipFactorizedRuntime.Session root = LmdbFusedSipFactorizedRuntime.create(19L, 1 << 20, true);
		try {
			try (LmdbFusedSipFactorizedRuntime.Scope ignored = LmdbFusedSipFactorizedRuntime.attach(root)) {
				LmdbFusedKernelRuntime.recordKernelBind("irKernel", new StubKernel());
			}
			Thread worker = new Thread(() -> {
				try (LmdbFusedSipFactorizedRuntime.Scope ignored = LmdbFusedSipFactorizedRuntime.inherit(root)) {
					LmdbFusedKernelRuntime.recordKernelBind("irKernelParallel", new StubKernel());
					LmdbFusedKernelRuntime.recordKernelBind("irKernelParallel", new StubKernel());
				}
			});
			worker.start();
			worker.join();

			LmdbFusedSipFactorizedRuntime.Telemetry telemetry = root.telemetry();
			assertEquals(2, telemetry.kernelBinds().size());
			assertEquals(1L, telemetry.kernelBinds().get("StubKernel route=irKernel"));
			assertEquals(2L, telemetry.kernelBinds().get("StubKernel route=irKernelParallel"));
		} finally {
			root.close();
		}
	}

	private static final class StubKernel implements org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.JaninoKernel {

		@Override
		public void bind(org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelContext context) {
		}

		@Override
		public int fill(long[] rowBuffer, int maxRows) {
			return 0;
		}
	}
}
